args.sparql:
SELECT DISTINCT ?artist ?artistLabel WHERE {
  { dbr:Znayu_Ya dbo:artist ?artist }
  UNION
  { dbr:Znayu_Ya dbp:artist ?artist }
  OPTIONAL { ?artist rdfs:label ?artistLabel . FILTER(lang(?artistLabel) = "en") }
}

SELECT DISTINCT ?birthPlace ?birthPlaceLabel WHERE {
  { dbr:Ruslana dbo:birthPlace ?birthPlace }
  UNION
  { dbr:Ruslana dbp:birthPlace ?birthPlace }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel) = "en") }
}

